import math

import adsk.core
import adsk.fusion


def _box(tbm, cx, cy, cz, lx, ly, lz):
    """An axis-aligned box in the GLOBAL X/Y/Z frame. mm in, cm internally."""
    obb = adsk.core.OrientedBoundingBox3D.create(
        adsk.core.Point3D.create(cx / 10.0, cy / 10.0, cz / 10.0),
        adsk.core.Vector3D.create(1.0, 0.0, 0.0),
        adsk.core.Vector3D.create(0.0, 1.0, 0.0),
        lx / 10.0, ly / 10.0, lz / 10.0)
    return tbm.createBox(obb)


def _cyl(tbm, x, y, z0, z1, r):
    """A cylinder on an axis PARALLEL TO Z, from z0 to z1. mm in, cm internally."""
    return tbm.createCylinderOrCone(
        adsk.core.Point3D.create(x / 10.0, y / 10.0, z0 / 10.0), r / 10.0,
        adsk.core.Point3D.create(x / 10.0, y / 10.0, z1 / 10.0), r / 10.0)


def _quadrant_axes(quadrant):
    """u = radial direction, v = tangential direction, at 90 deg * quadrant about Z."""
    a = math.radians(quadrant * 90.0)
    u = adsk.core.Vector3D.create(math.cos(a), math.sin(a), 0.0)
    v = adsk.core.Vector3D.create(-math.sin(a), math.cos(a), 0.0)
    return u, v


def _quadrant_box(tbm, quadrant, r_lo, r_hi, y_lo, y_hi, z_lo, z_hi):
    """A box whose length runs radially and width tangentially, at a given quadrant
    (0/1/2/3 = 0/90/180/270 deg about the rocket Z axis) -- ports
    `cad/canard_bay.fs`'s `quadrantCuboid`. mm in, cm internally.
    """
    u, v = _quadrant_axes(quadrant)
    r_lo, r_hi = min(r_lo, r_hi), max(r_lo, r_hi)
    y_lo, y_hi = min(y_lo, y_hi), max(y_lo, y_hi)
    z_lo, z_hi = min(z_lo, z_hi), max(z_lo, z_hi)
    rc, yc, zc = (r_lo + r_hi) / 2.0, (y_lo + y_hi) / 2.0, (z_lo + z_hi) / 2.0
    center = adsk.core.Point3D.create(
        (u.x * rc + v.x * yc) / 10.0, (u.y * rc + v.y * yc) / 10.0, zc / 10.0)
    obb = adsk.core.OrientedBoundingBox3D.create(
        center, u, v, (r_hi - r_lo) / 10.0, (y_hi - y_lo) / 10.0, (z_hi - z_lo) / 10.0)
    return tbm.createBox(obb)


def _radial_cyl(tbm, quadrant, across, z, r0, r1, r):
    """A cylinder on a RADIAL axis at the given quadrant, spanning radius r0 -> r1, offset
    `across` tangentially -- ports `cad/canard_bay.fs`'s `radialCylinder`. mm in, cm
    internally.
    """
    u, v = _quadrant_axes(quadrant)
    bx, by = v.x * across, v.y * across
    p0 = adsk.core.Point3D.create((bx + u.x * r0) / 10.0, (by + u.y * r0) / 10.0, z / 10.0)
    p1 = adsk.core.Point3D.create((bx + u.x * r1) / 10.0, (by + u.y * r1) / 10.0, z / 10.0)
    return tbm.createCylinderOrCone(p0, r / 10.0, p1, r / 10.0)


def _cut(tbm, target, tool, what):
    """Boolean subtract. NOTE: booleanOperation returns a BOOL and mutates `target` in
    place -- never assign its result back, per make_sled_fusion.py's own warning.
    """
    if not tbm.booleanOperation(target, tool, adsk.fusion.BooleanTypes.DifferenceBooleanType):
        raise ValueError("cut %s did not take" % what)


def _union(tbm, target, tool, what):
    if not tbm.booleanOperation(target, tool, adsk.fusion.BooleanTypes.UnionBooleanType):
        raise ValueError("union %s did not take" % what)


def _get_or_create_component(root, name):
    """Find an existing occurrence by component name, else create a new empty one.

    Returns (occurrence, already_has_bodies). A caller that finds `already_has_bodies`
    True should verify rather than rebuild -- the same idempotency rule
    `make_sled_fusion.py` uses.
    """
    for o in root.occurrences:
        if o.component.name == name:
            return o, o.component.bRepBodies.count > 0
    occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
    occ.component.name = name
    return occ, False


def _inject(comp, made):
    """Inject a list of (name, body) temporary BRep bodies through one BaseFeature.

    Mandatory for a parametric document: a temp body only "takes" via
    `BRepBodies.add(body, baseFeature)`, per make_sled_fusion.py's own header.
    """
    bf = comp.features.baseFeatures.add()
    bf.startEdit()
    for (name, body) in made:
        b = comp.bRepBodies.add(body, bf)
        b.name = name
    bf.finishEdit()


def _verify_volume(comp, want, tol, loose=(), loose_tol=None):
    """Compare each named body's volume (mm3) against an analytic expectation.

    `loose` names bodies (radial holes through curved walls, or a part whose analytic
    figure is itself an estimate) that get `loose_tol` instead of `tol` -- measured, not
    guessed, the same discipline make_sled_fusion.py's PORT_VOLUME_TOLERANCE_PER_PORT uses.
    Returns a list of violation strings (empty if everything is within tolerance).
    """
    acc = adsk.fusion.CalculationAccuracy.VeryHighCalculationAccuracy
    got = {}
    for b in comp.bRepBodies:
        got[b.name] = b.getPhysicalProperties(acc).volume * 1e3
    bad = []
    for name, wv in want.items():
        if name not in got:
            bad.append("%s is missing" % name)
            continue
        t = loose_tol if (name in loose and loose_tol is not None) else tol
        d = got[name] - wv
        print("  %-28s %14.4f mm3  want %14.4f  delta %+9.4f  (tol %.3f)"
              % (name, got[name], wv, d, t))
        if abs(d) > t:
            bad.append("%s is %+.4f mm3 out" % (name, d))
    return bad


def _verify_cyl_faces(body, radius, axis_is_radial):
    """Count cylindrical faces at `radius` (mm) and read back their clocking, in degrees
    mod 180. `axis_is_radial` True keeps only faces whose axis has no Z component (a
    radial hole); False keeps only faces whose axis IS parallel to Z (an axial hole).
    Exact where a volume check on a radial hole through a curved wall is not -- see
    make_sled_fusion.py's header for why that matters.
    """
    found = []
    for f in body.faces:
        g = f.geometry
        if not g.objectType.endswith("Cylinder"):
            continue
        if abs(g.radius * 10.0 - radius) > 1e-6:
            continue
        ax = g.axis
        is_radial = abs(ax.z) < 1e-9
        if is_radial != axis_is_radial:
            continue
        found.append(math.degrees(math.atan2(ax.y, ax.x)) % 180.0)
    return sorted(found)


OVER = 1.0   # mm, overshoot on every open-face cut/join -- see fusion_common.py's header

TUBE_OR = 39.7000
TUBE_IR = 37.4000
TUBE_LEN = 142.9200
TUBE_VOLUME = 79158.0931
TUBE_BORE_TOLERANCE = 0.8000
WALL_BORE_DIA = 8.0000

HINGE_Z = 68.2690
JOURNAL_R = 3.0000
SLEEVE_INBOARD = 33.4850
PANEL_ROOT = 40.2000
SLEEVE_LENGTH = 6.7150

TANG_THICKNESS = 1.8000
TANG_WIDTH = 11.9000
ENGAGEMENT = 25.5000
BOND_LINE = 0.1000
TANG_OVERSHOOT = 0.4000
SLOT_THICKNESS = 2.0000
SLOT_WIDTH = 12.1000

SOCKET_DIA = 4.1000
SOCKET_DEPTH = 3.2000

TIP_R = 107.1900
ROOT_LE = 38.0698
ROOT_TE = 105.2598
TIP_LE = 85.6111
TIP_TE = 112.6071
PANEL_THICKNESS = 3.2000

SHAFT_VOLUME = 698.1377
PANEL_VOLUME = 9475.7122
VOLUME_TOLERANCE = 0.0200


def build_tube(root):
    occ, has_bodies = _get_or_create_component(root, "Tube")
    if has_bodies:
        print("Tube already holds a body -- verifying rather than rebuilding")
        verify_tube(occ.component)
        return
    comp = occ.component
    tbm = adsk.fusion.TemporaryBRepManager.get()
    outer = _cyl(tbm, 0.0, 0.0, 0.0, TUBE_LEN, TUBE_OR)
    _cut(tbm, outer, _cyl(tbm, 0.0, 0.0, -OVER, TUBE_LEN + OVER, TUBE_IR), "bore")
    # Four wall bores, one per hinge axis -- the bearing seat (HingeStack.wall_bore_dia).
    # Missing from M3's first pass; see the emit()-side comment on TUBE_BORE_TOLERANCE.
    for q in range(4):
        wall_bore = _radial_cyl(tbm, q, 0.0, HINGE_Z, TUBE_IR - OVER, TUBE_OR + OVER,
                                WALL_BORE_DIA / 2.0)
        _cut(tbm, outer, wall_bore, "wall bore %d" % q)
    _inject(comp, [("tube", outer)])
    print("built 1 body in Tube")
    verify_tube(comp)


def verify_tube(comp):
    """Volume loosened for the four wall bores (radial holes through a curved wall --
    see emit()'s comment), plus an exact face check on them: right count, right
    diameter, right clocking, where the volume figure is not exact."""
    bad = _verify_volume(comp, {"tube": TUBE_VOLUME}, VOLUME_TOLERANCE,
                         loose=("tube",), loose_tol=TUBE_BORE_TOLERANCE)

    body = None
    for b in comp.bRepBodies:
        if b.name == "tube":
            body = b
    if body is None:
        bad.append("tube body is missing, so its wall bores cannot be checked")
    else:
        found = _verify_cyl_faces(body, WALL_BORE_DIA / 2.0, axis_is_radial=True)
        print("  %-28s %d wall-bore faces at dia %.2f, axes %s deg"
              % ("tube", len(found), WALL_BORE_DIA, ["%.2f" % v for v in found]))
        if len(found) != 4:
            bad.append("tube has %d wall-bore faces, wanted 4" % len(found))
        else:
            for a in found:
                if min(abs(a - 0.0), abs(a - 90.0)) > 1e-6:
                    bad.append("a wall bore is clocked %.4f deg, wanted 0 or 90" % a)

    if bad:
        raise ValueError("VERIFY FAILED: " + "; ".join(bad))
    print("  OK")


def build_panel(root, q):
    name = "Panel%d" % q
    occ, has_bodies = _get_or_create_component(root, name)
    if has_bodies:
        print("%s already holds a body -- verifying rather than rebuilding" % name)
        verify_one(occ.component, "panel", PANEL_VOLUME)
        return
    comp = occ.component
    tbm = adsk.fusion.TemporaryBRepManager.get()

    # ---- the trapezoid, built as a real parametric feature in a disposable scratch
    #      component, then lifted into a temp body so everything past this point stays
    #      on the same pattern as the rest of the migration -- see the module docstring.
    a = math.radians(q * 90.0)
    ux, uy = math.cos(a), math.sin(a)

    def pt(r, z):
        return adsk.core.Point3D.create(ux * r / 10.0, uy * r / 10.0, z / 10.0)

    scratch_occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
    scratch = scratch_occ.component
    plane = scratch.xZConstructionPlane if q in (0, 2) else scratch.yZConstructionPlane
    sk = scratch.sketches.add(plane)
    corners = [pt(PANEL_ROOT, ROOT_LE), pt(TIP_R, TIP_LE), pt(TIP_R, TIP_TE), pt(PANEL_ROOT, ROOT_TE)]
    sk_pts = [sk.modelToSketchSpace(c) for c in corners]
    lines = sk.sketchCurves.sketchLines
    first = lines.addByTwoPoints(
        adsk.core.Point3D.create(sk_pts[0].x, sk_pts[0].y, 0.0),
        adsk.core.Point3D.create(sk_pts[1].x, sk_pts[1].y, 0.0))
    prev = first
    for sp in sk_pts[2:]:
        prev = lines.addByTwoPoints(prev.endSketchPoint, adsk.core.Point3D.create(sp.x, sp.y, 0.0))
    lines.addByTwoPoints(prev.endSketchPoint, first.startSketchPoint)

    prof = sk.profiles.item(0)
    exin = scratch.features.extrudeFeatures.createInput(
        prof, adsk.fusion.FeatureOperations.NewBodyFeatureOperation)
    exin.setSymmetricExtent(adsk.core.ValueInput.createByReal(PANEL_THICKNESS / 10.0), True)
    feat = scratch.features.extrudeFeatures.add(exin)
    raw = tbm.copy(feat.bodies.item(0))
    scratch_occ.deleteMe()

    # ---- the tang slot, cut from the lifted temp body exactly like every other cut
    #      in this migration. SLOT_THICKNESS runs tangentially (Y, through the panel's
    #      own thickness -- it has to fit inside PANEL_THICKNESS) and SLOT_WIDTH runs
    #      axially (Z, chordwise -- it is what leading_edge_clearance/trailing_edge_
    #      clearance in design/hinge.py measure against the swept LE/TE). Swapping these
    #      is the bug this generator's own verify() caught on the first run: a slot cut
    #      only ~2 mm wide in Z instead of ~12 mm removed a quarter of the material it
    #      should have. ----
    slot = _quadrant_box(tbm, q, PANEL_ROOT - OVER, PANEL_ROOT + ENGAGEMENT + BOND_LINE,
                         -SLOT_THICKNESS / 2.0, SLOT_THICKNESS / 2.0,
                         HINGE_Z - SLOT_WIDTH / 2.0, HINGE_Z + SLOT_WIDTH / 2.0)
    _cut(tbm, raw, slot, "tang slot")

    _inject(comp, [("panel", raw)])
    print("built 1 body in %s" % name)
    verify_one(comp, "panel", PANEL_VOLUME)


def build_shaft(root, q):
    name = "Shaft%d" % q
    occ, has_bodies = _get_or_create_component(root, name)
    if has_bodies:
        print("%s already holds a body -- verifying rather than rebuilding" % name)
        verify_one(occ.component, "shaft", SHAFT_VOLUME)
        return
    comp = occ.component
    tbm = adsk.fusion.TemporaryBRepManager.get()

    rod = _radial_cyl(tbm, q, 0.0, HINGE_Z, SLEEVE_INBOARD, PANEL_ROOT, JOURNAL_R)
    # TANG_THICKNESS runs tangentially (Y), TANG_WIDTH runs axially (Z, chordwise) --
    # see build_panel's own comment on the matching slot cut for why.
    tang = _quadrant_box(tbm, q, PANEL_ROOT - TANG_OVERSHOOT, PANEL_ROOT + ENGAGEMENT,
                         -TANG_THICKNESS / 2.0, TANG_THICKNESS / 2.0,
                         HINGE_Z - TANG_WIDTH / 2.0, HINGE_Z + TANG_WIDTH / 2.0)
    _union(tbm, rod, tang, "tang boss")

    socket = _radial_cyl(tbm, q, 0.0, HINGE_Z, SLEEVE_INBOARD - OVER,
                         SLEEVE_INBOARD + SOCKET_DEPTH, SOCKET_DIA / 2.0)
    _cut(tbm, rod, socket, "spline socket")

    _inject(comp, [("shaft", rod)])
    print("built 1 body in %s" % name)
    verify_one(comp, "shaft", SHAFT_VOLUME)


def verify_one(comp, expected_name, want_volume):
    bad = _verify_volume(comp, {expected_name: want_volume}, VOLUME_TOLERANCE)
    if bad:
        raise ValueError("VERIFY FAILED: " + "; ".join(bad))
    print("  OK")


def run(_context: str):
    app = adsk.core.Application.get()
    des = adsk.fusion.Design.cast(app.activeProduct)
    root = des.rootComponent

    build_tube(root)
    for q in range(4):
        build_panel(root, q)
    for q in range(4):
        build_shaft(root, q)
